<style scoped>
div.model-wrap {
  width: 90%;
  /* background: red; */
  margin: 50px 0 0 0;
  display: flex;
  flex-direction: column;
  align-items: center;

  /* outline: 2px solid black; */
}

div.model-wrap .instructions {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  color: #676767;
  font-size: 13px;
  border-bottom: 1px solid #d9d9d9;
  /* border-radius: 5px; */
  background-color: #fafafa;
  padding: 11px 0 11px 0;
  margin: 0 0 20px 0;
}

div.model-wrap .instructions h1 {
  font-size: 14px;
  margin: 0 0 20px 0;
}

div.model-wrap svg.body-map {
  height: 90vh;
}

button.hover-info {
  border: 1px solid #d9d9d9;
  padding: 7px 16px 7px 16px;
  font-size: 13px;
  color: #676767;
  cursor: pointer;
  border-radius: 5px;
  margin: 5px 5px 0 0;
  display: flex;
  align-items: center;
}

button.hover-info svg {
  margin: 0 0 0 5px;
}

path,
.map-switcher {
  cursor: pointer;
}

@media screen and (max-width: 1050px) {
  div.model-wrap {
    margin: 35px 0 0 0;
  }
}

@media screen and (max-width: 480px) {
  div.model-wrap svg.body-map {
    height: fit-content;
  }

  div.model-wrap {
    justify-content: center;
  }
}
</style>
